export function execute({ operation, input, state, now }) {
  const entries = state?.entries ?? [];

  if (operation === "submit") {
    const name = String(input?.name ?? "").trim();
    const message = String(input?.message ?? "").trim();

    if (name.length === 0 || message.length === 0) {
      return { result: { status: "invalid", message: "Enter a name and message." }, state: { entries } };
    }

    if (entries.length >= 12) {
      return { result: { status: "full", message: "Guestbook full." }, state: { entries } };
    }

    const newEntry = { name, message, createdAt: now };
    const nextEntries = [...entries, newEntry];
    return { result: { status: "saved", message: `Saved, ${name}.` }, state: { entries: nextEntries } };
  }

  if (operation === "latest") {
    const latest = entries.slice(-3).reverse();
    return { result: latest, state: { entries } };
  }

  throw new Error(`Unknown operation: ${operation}`);
}

import { describe, it } from "node:test";
import assert from "node:assert";
import { execute } from "../src/guestbook.mjs";

describe("submit", () => {
  it("trims and saves an entry", () => {
    const { result, state } = execute({
      operation: "submit",
      input: { name: " Ari ", message: " Hello " },
      state: { entries: [] },
      now: 100,
    });
    assert.deepStrictEqual(result, { status: "saved", message: "Saved, Ari." });
    assert.deepStrictEqual(state, { entries: [{ name: "Ari", message: "Hello", createdAt: 100 }] });
  });

  it("rejects blank name", () => {
    const state = { entries: [] };
    const { result, state: nextState } = execute({
      operation: "submit",
      input: { name: "", message: "Hi" },
      state,
      now: 100,
    });
    assert.deepStrictEqual(result, { status: "invalid", message: "Enter a name and message." });
    assert.deepStrictEqual(nextState, state);
  });

  it("rejects blank message", () => {
    const state = { entries: [] };
    const { result, state: nextState } = execute({
      operation: "submit",
      input: { name: "Ari", message: "   " },
      state,
      now: 100,
    });
    assert.deepStrictEqual(result, { status: "invalid", message: "Enter a name and message." });
    assert.deepStrictEqual(nextState, state);
  });

  it("rejects when full", () => {
    const entries = Array.from({ length: 12 }, (_, i) => ({
      name: `Person ${i}`,
      message: `Message ${i}`,
      createdAt: i,
    }));
    const state = { entries };
    const { result, state: nextState } = execute({
      operation: "submit",
      input: { name: "Ari", message: "Hi" },
      state,
      now: 100,
    });
    assert.deepStrictEqual(result, { status: "full", message: "Guestbook full." });
    assert.deepStrictEqual(nextState, state);
  });

  it("supports Unicode", () => {
    const { result, state } = execute({
      operation: "submit",
      input: { name: " 猫 ", message: " 你好 🎉 " },
      state: { entries: [] },
      now: 200,
    });
    assert.deepStrictEqual(result, { status: "saved", message: "Saved, 猫." });
    assert.deepStrictEqual(state, { entries: [{ name: "猫", message: "你好 🎉", createdAt: 200 }] });
  });
});

describe("latest", () => {
  it("returns up to three newest entries, newest first", () => {
    const state = {
      entries: [
        { name: "A", message: "1", createdAt: 1 },
        { name: "B", message: "2", createdAt: 2 },
        { name: "C", message: "3", createdAt: 3 },
        { name: "D", message: "4", createdAt: 4 },
      ],
    };
    const { result, state: nextState } = execute({
      operation: "latest",
      input: null,
      state,
      now: 10,
    });
    assert.deepStrictEqual(result, [
      { name: "D", message: "4", createdAt: 4 },
      { name: "C", message: "3", createdAt: 3 },
      { name: "B", message: "2", createdAt: 2 },
    ]);
    assert.deepStrictEqual(nextState, state);
  });

  it("returns fewer than three when not enough entries", () => {
    const state = {
      entries: [{ name: "A", message: "1", createdAt: 1 }],
    };
    const { result } = execute({ operation: "latest", input: null, state, now: 10 });
    assert.deepStrictEqual(result, [{ name: "A", message: "1", createdAt: 1 }]);
  });

  it("returns empty when no entries", () => {
    const { result } = execute({ operation: "latest", input: null, state: { entries: [] }, now: 10 });
    assert.deepStrictEqual(result, []);
  });
});

// Pure guestbook logic. The host validates inputs and durably commits state.
export function execute({ operation, input, state, now, connectionResults = [] }) {
  if (operation === 'latest') {
    return {
      result: state.entries.slice(-3).reverse().map(entry => ({ ...entry })),
      state,
    };
  }

  if (operation === 'submit') {
    const name = input.name.trim();
    const message = input.message.trim();

    if (name.length === 0 || message.length === 0) {
      return {
        result: { status: 'invalid', message: 'Enter a name and message.' },
        state,
      };
    }

    if (state.entries.length >= 12) {
      return {
        result: { status: 'full', message: 'Guestbook full.' },
        state,
      };
    }

    return {
      result: { status: 'saved', message: `Saved, ${name}.` },
      state: {
        entries: [...state.entries, { name, message, createdAt: now }],
      },
    };
  }

  throw new Error('Unknown guestbook operation.');
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { execute } from '../src/guestbook.mjs';

function submit(state, name, message, now = 100) {
  return execute({ operation: 'submit', input: { name, message }, state, now });
}
function latest(state) {
  return execute({ operation: 'latest', input: null, state, now: 100 });
}
function entries(count) {
  return Array.from({ length: count }, (_, i) => ({ name: `Guest ${i + 1}`, message: `Message ${i + 1}`, createdAt: i + 1 }));
}
function freezeState(state) {
  for (const entry of state.entries) Object.freeze(entry);
  Object.freeze(state.entries);
  return Object.freeze(state);
}

test('immutable agreement: save-and-read', () => {
  const initial = freezeState({ entries: [] });
  const saved = submit(initial, ' Ari ', ' Hello ', 100);
  const expectedState = { entries: [{ name: 'Ari', message: 'Hello', createdAt: 100 }] };
  assert.deepEqual(saved, { result: { status: 'saved', message: 'Saved, Ari.' }, state: expectedState });
  assert.deepEqual(initial, { entries: [] });
  assert.deepEqual(latest(saved.state), { result: expectedState.entries, state: expectedState });
});

test('either blank field is invalid and leaves existing entries unchanged', () => {
  const state = freezeState({ entries: entries(2) });
  for (const [name, message] of [['', 'Hi'], ['Name', ''], [' \t\n', 'Hi'], ['Name', '\u2003\u3000\r\n'], ['', '']]) {
    const output = submit(state, name, message);
    assert.deepEqual(output.result, { status: 'invalid', message: 'Enter a name and message.' });
    assert.strictEqual(output.state, state);
  }
});

test('Unicode full names and messages are preserved, apart from outer whitespace', () => {
  const name = '李 小龍 — Zoë 👩🏽‍💻';
  const message = 'こんにちは 🌍\nمرحبا! e\u0301 <b>hello</b>';
  const output = submit(freezeState({ entries: [] }), `\u3000${name}\u2003`, `\n${message}\t`, 9999999999999);
  assert.deepEqual(output, {
    result: { status: 'saved', message: `Saved, ${name}.` },
    state: { entries: [{ name, message, createdAt: 9999999999999 }] },
  });
});

test('full schema-size strings are saved without truncation', () => {
  const name = '😀'.repeat(20);
  const message = '界'.repeat(341) + 'a';
  assert.equal(Buffer.byteLength(name, 'utf8'), 80);
  assert.equal(Buffer.byteLength(message, 'utf8'), 1024);
  const output = submit({ entries: [] }, name, message, 0);
  assert.equal(output.state.entries[0].name, name);
  assert.equal(output.state.entries[0].message, message);
  assert.equal(output.state.entries[0].createdAt, 0);
  assert.equal(output.result.message, `Saved, ${name}.`);
  assert.ok(Buffer.byteLength(output.result.message, 'utf8') <= 512);
});

test('latest returns zero to three entries newest-first without mutating state', () => {
  for (let count = 0; count <= 12; count++) {
    const state = freezeState({ entries: entries(count) });
    const output = latest(state);
    assert.strictEqual(output.state, state);
    assert.deepEqual(output.result, entries(count).slice(-3).reverse());
    assert.ok(output.result.length <= 3);
    if (count > 0) {
      output.result[0].name = 'Changed only in result';
      assert.equal(state.entries[count - 1].name, `Guest ${count}`);
    }
  }
});

test('newest follows append order even when supplied timestamps tie or decrease', () => {
  let state = { entries: [] };
  const times = [50, 50, 10, 0];
  for (let i = 0; i < times.length; i++) state = submit(state, `Person ${i}`, `Text ${i}`, times[i]).state;
  assert.deepEqual(latest(state).result, [
    { name: 'Person 3', message: 'Text 3', createdAt: 0 },
    { name: 'Person 2', message: 'Text 2', createdAt: 10 },
    { name: 'Person 1', message: 'Text 1', createdAt: 50 },
  ]);
});

test('twelfth submission saves; subsequent competing committed submission is full', () => {
  const initial = freezeState({ entries: entries(11) });
  const first = submit(initial, 'Last Guest', 'Last space', 200);
  assert.deepEqual(first.result, { status: 'saved', message: 'Saved, Last Guest.' });
  assert.equal(first.state.entries.length, 12);
  assert.deepEqual(first.state.entries.slice(0, 11), initial.entries);
  assert.equal(initial.entries.length, 11);
  const fullState = freezeState(first.state);
  const second = submit(fullState, 'Another Guest', 'No space', 201);
  assert.deepEqual(second.result, { status: 'full', message: 'Guestbook full.' });
  assert.strictEqual(second.state, fullState);
  assert.deepEqual(latest(fullState).result, [
    { name: 'Last Guest', message: 'Last space', createdAt: 200 },
    { name: 'Guest 11', message: 'Message 11', createdAt: 11 },
    { name: 'Guest 10', message: 'Message 10', createdAt: 10 },
  ]);
});

test('blank input is invalid even when the guestbook is full', () => {
  const state = freezeState({ entries: entries(12) });
  const output = submit(state, ' \n ', 'Hello');
  assert.deepEqual(output.result, { status: 'invalid', message: 'Enter a name and message.' });
  assert.strictEqual(output.state, state);
});

test('invocations use supplied state, not process memory', () => {
  submit({ entries: [] }, 'One', 'First');
  assert.deepEqual(latest({ entries: [] }), { result: [], state: { entries: [] } });
  assert.deepEqual(submit({ entries: [] }, 'Two', 'Second', 123).state, {
    entries: [{ name: 'Two', message: 'Second', createdAt: 123 }],
  });
});

// The host supplies and commits durable state. No bookings live in process memory.
// Schema validation and serialized write access are enforced by the host.
export function execute({ operation, input, state, now, connectionResults = [] }) {
  if (operation === 'guests') {
    return { result: [...state.guests], state };
  }

  if (operation !== 'join' && operation !== 'cancel') {
    throw new Error('Unknown operation');
  }

  const name = input.name.trim();
  if (name.length === 0) {
    return { result: 'invalid', state };
  }

  const index = state.guests.indexOf(name);
  if (operation === 'join') {
    // Idempotency takes priority even when the list is full.
    if (index !== -1) return { result: 'already_joined', state };
    if (state.guests.length >= state.capacity) return { result: 'full', state };
    return {
      result: 'accepted',
      state: { capacity: state.capacity, guests: [...state.guests, name] }
    };
  }

  if (index === -1) return { result: 'not_joined', state };
  return {
    result: 'removed',
    state: { capacity: state.capacity, guests: state.guests.filter(guest => guest !== name) }
  };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { execute } from '../src/booking.mjs';

function run(operation, input, state) {
  const before = structuredClone(state);
  const output = execute({ operation, input, state, now: 100, connectionResults: [] });
  assert.deepEqual(state, before, 'the input state must not be mutated');
  assert.deepEqual(Object.keys(output).sort(), ['result', 'state']);
  return output;
}

function step(state, operation, input, result, guests) {
  const output = run(operation, input, state);
  assert.deepEqual(output, { result, state: { capacity: state.capacity, guests } });
  return output.state;
}

test('immutable agreement: last place and cancellation', () => {
  let state = { capacity: 1, guests: [] };
  state = step(state, 'join', { name: 'Ari' }, 'accepted', ['Ari']);
  state = step(state, 'join', { name: 'Bo' }, 'full', ['Ari']);
  state = step(state, 'cancel', { name: 'Ari' }, 'removed', []);
  step(state, 'guests', null, [], []);
});

test('repeated acceptance never consumes another place, including at capacity', () => {
  let state = { capacity: 2, guests: [] };
  state = step(state, 'join', { name: ' Ari ' }, 'accepted', ['Ari']);
  state = step(state, 'join', { name: 'Ari' }, 'already_joined', ['Ari']);
  state = step(state, 'join', { name: 'Bo' }, 'accepted', ['Ari', 'Bo']);
  state = step(state, 'join', { name: '\tAri\n' }, 'already_joined', ['Ari', 'Bo']);
  step(state, 'join', { name: 'Cy' }, 'full', ['Ari', 'Bo']);
});

test('competing sequential writes cannot both take the final place; cancellation frees it', () => {
  let state = { capacity: 1, guests: [] };
  state = step(state, 'join', { name: 'Ari' }, 'accepted', ['Ari']);
  state = step(state, 'join', { name: 'Bo' }, 'full', ['Ari']);
  state = step(state, 'cancel', { name: ' Ari ' }, 'removed', []);
  state = step(state, 'join', { name: 'Bo' }, 'accepted', ['Bo']);
  step(state, 'cancel', { name: 'Ari' }, 'not_joined', ['Bo']);
});

test('blank names are invalid and missing cancellation is idempotent', () => {
  const state = { capacity: 1, guests: ['Ari'] };
  for (const name of ['', ' ', '\t\n', '\u2003']) {
    step(state, 'join', { name }, 'invalid', ['Ari']);
    step(state, 'cancel', { name }, 'invalid', ['Ari']);
  }
  step(state, 'cancel', { name: 'Missing' }, 'not_joined', ['Ari']);
  let empty = step(state, 'cancel', { name: 'Ari' }, 'removed', []);
  step(empty, 'cancel', { name: 'Ari' }, 'not_joined', []);
});

test('names are case-sensitive; retained order survives removal and rejoining', () => {
  let state = { capacity: 4, guests: [] };
  state = step(state, 'join', { name: 'Ari' }, 'accepted', ['Ari']);
  state = step(state, 'join', { name: 'ari' }, 'accepted', ['Ari', 'ari']);
  state = step(state, 'join', { name: 'Bo' }, 'accepted', ['Ari', 'ari', 'Bo']);
  state = step(state, 'cancel', { name: 'ARI' }, 'not_joined', ['Ari', 'ari', 'Bo']);
  state = step(state, 'cancel', { name: 'ari' }, 'removed', ['Ari', 'Bo']);
  state = step(state, 'join', { name: 'ari' }, 'accepted', ['Ari', 'Bo', 'ari']);
  step(state, 'guests', null, ['Ari', 'Bo', 'ari'], ['Ari', 'Bo', 'ari']);
});

test('zero capacity and maximum capacity boundaries', () => {
  step({ capacity: 0, guests: [] }, 'join', { name: 'Ari' }, 'full', []);
  let state = { capacity: 12, guests: [] };
  for (let i = 0; i < 12; i++) {
    state = step(state, 'join', { name: `Guest${i}` }, 'accepted', [...state.guests, `Guest${i}`]);
  }
  step(state, 'join', { name: 'Overflow' }, 'full', state.guests);
  step(state, 'join', { name: 'Guest11' }, 'already_joined', state.guests);
});

test('maximum-byte names and Unicode names remain exact identities', () => {
  let state = { capacity: 3, guests: [] };
  for (const name of ['x'.repeat(80), 'é'.repeat(40), '李']) {
    assert.ok(Buffer.byteLength(name, 'utf8') <= 80);
    state = step(state, 'join', { name }, 'accepted', [...state.guests, name]);
  }
  step(state, 'cancel', { name: ' 李 ' }, 'removed', state.guests.slice(0, 2));
});

test('restored serialized host state works with a fresh module instance', async () => {
  const first = run('join', { name: 'Ari' }, { capacity: 2, guests: [] });
  const restored = JSON.parse(JSON.stringify(first.state));
  const fresh = await import('../src/booking.mjs?restart-test');
  assert.deepEqual(fresh.execute({ operation: 'guests', input: null, state: restored, now: 200 }), {
    result: ['Ari'], state: { capacity: 2, guests: ['Ari'] }
  });
  assert.deepEqual(fresh.execute({ operation: 'join', input: { name: 'Ari' }, state: restored, now: 200 }), {
    result: 'already_joined', state: { capacity: 2, guests: ['Ari'] }
  });
  assert.deepEqual(fresh.execute({ operation: 'cancel', input: { name: 'Ari' }, state: restored, now: 200 }), {
    result: 'removed', state: { capacity: 2, guests: [] }
  });
});

test('read result is independent of retained state and frozen inputs are supported', () => {
  const state = Object.freeze({ capacity: 2, guests: Object.freeze(['Ari']) });
  const output = run('guests', null, state);
  output.result.push('Not retained');
  assert.deepEqual(state.guests, ['Ari']);
  step(state, 'join', Object.freeze({ name: 'Bo' }), 'accepted', ['Ari', 'Bo']);
  step(state, 'cancel', Object.freeze({ name: 'Ari' }), 'removed', []);
});

function trimName(name) {
  return typeof name === 'string' ? name.trim() : '';
}

export function execute({ operation, input, state, now, connectionResults = [] }) {
  const capacity = state.capacity;
  const guests = state.guests.slice();

  if (operation === 'join') {
    const n = trimName(input.name);
    if (n === '') {
      return { result: 'invalid', state: { capacity, guests } };
    }
    if (guests.includes(n)) {
      return { result: 'already_joined', state: { capacity, guests } };
    }
    if (guests.length >= capacity) {
      return { result: 'full', state: { capacity, guests } };
    }
    return { result: 'accepted', state: { capacity, guests: [...guests, n] } };
  }

  if (operation === 'cancel') {
    const n = trimName(input.name);
    if (n === '') {
      return { result: 'invalid', state: { capacity, guests } };
    }
    const idx = guests.indexOf(n);
    if (idx === -1) {
      return { result: 'not_joined', state: { capacity, guests } };
    }
    const next = guests.slice(0, idx).concat(guests.slice(idx + 1));
    return { result: 'removed', state: { capacity, guests: next } };
  }

  if (operation === 'guests') {
    return { result: guests, state: { capacity, guests } };
  }

  throw new Error('Unknown operation: ' + operation);
}

import { test } from 'node:test';
import assert from 'node:assert';
import { execute } from '../src/index.mjs';

function runSteps(initialState, steps) {
  let state = initialState;
  for (const step of steps) {
    const output = execute({
      operation: step.operation,
      input: step.input ?? null,
      state,
      now: step.now,
    });
    assert.deepStrictEqual(output.result, step.expected.result);
    state = output.state;
    assert.deepStrictEqual(state, step.expected.state);
  }
  return state;
}

test('last-place-and-cancel', () => {
  runSteps({ capacity: 1, guests: [] }, [
    {
      operation: 'join',
      input: { name: 'Ari' },
      now: 100,
      expected: { state: { capacity: 1, guests: ['Ari'] }, result: 'accepted' },
    },
    {
      operation: 'join',
      input: { name: 'Bo' },
      now: 100,
      expected: { state: { capacity: 1, guests: ['Ari'] }, result: 'full' },
    },
    {
      operation: 'cancel',
      input: { name: 'Ari' },
      now: 100,
      expected: { state: { capacity: 1, guests: [] }, result: 'removed' },
    },
    {
      operation: 'guests',
      input: null,
      now: 100,
      expected: { state: { capacity: 1, guests: [] }, result: [] },
    },
  ]);
});

test('join trims names and rejects blanks', () => {
  let state = { capacity: 2, guests: [] };
  let out = execute({ operation: 'join', input: { name: '   ' }, state, now: 1 });
  assert.equal(out.result, 'invalid');
  assert.deepStrictEqual(out.state.guests, []);

  out = execute({ operation: 'join', input: { name: '  Ari  ' }, state, now: 1 });
  assert.equal(out.result, 'accepted');
  assert.deepStrictEqual(out.state.guests, ['Ari']);
  state = out.state;

  out = execute({ operation: 'join', input: { name: 'Ari ' }, state, now: 1 });
  assert.equal(out.result, 'already_joined');
});

test('names are case-sensitive identities', () => {
  let state = { capacity: 2, guests: ['Ari'] };
  let out = execute({ operation: 'join', input: { name: 'ari' }, state, now: 1 });
  assert.equal(out.result, 'accepted');
  state = out.state;
  assert.deepStrictEqual(state.guests, ['Ari', 'ari']);

  out = execute({ operation: 'cancel', input: { name: 'Ari' }, state, now: 1 });
  assert.equal(out.result, 'removed');
  assert.deepStrictEqual(out.state.guests, ['ari']);
});

test('cancel trims and reports not_joined', () => {
  let state = { capacity: 2, guests: ['Ari'] };
  let out = execute({ operation: 'cancel', input: { name: '  Bo  ' }, state, now: 1 });
  assert.equal(out.result, 'not_joined');
  assert.deepStrictEqual(out.state.guests, ['Ari']);

  out = execute({ operation: 'cancel', input: { name: '  Ari  ' }, state, now: 1 });
  assert.equal(out.result, 'removed');
  assert.deepStrictEqual(out.state.guests, []);

  out = execute({ operation: 'cancel', input: { name: '   ' }, state: out.state, now: 1 });
  assert.equal(out.result, 'invalid');
});

test('guests returns retained order without changing state', () => {
  const state = { capacity: 3, guests: ['Bo', 'Ari'] };
  const out = execute({ operation: 'guests', input: null, state, now: 1 });
  assert.deepStrictEqual(out.result, ['Bo', 'Ari']);
  assert.deepStrictEqual(out.state, state);
});

test('capacity zero is immediately full', () => {
  const state = { capacity: 0, guests: [] };
  const out = execute({ operation: 'join', input: { name: 'Ari' }, state, now: 1 });
  assert.equal(out.result, 'full');
  assert.deepStrictEqual(out.state.guests, []);
