export function execute({ operation, input, state, now }) {
  if (operation === 'vote') {
    return vote(input, state, now);
  }
  if (operation === 'tally') {
    return tally(state, now);
  }
  throw new Error(`Unknown operation: ${operation}`);
}

function vote(input, state, now) {
  if (now >= state.closesAt) {
    return { result: 'closed', state };
  }

  const voter = typeof input.voter === 'string' ? input.voter.trim() : '';
  const choice = input.choice;

  if (voter === '') {
    return { result: 'invalid', state };
  }

  const existingIndex = state.votes.findIndex((v) => v.voter === voter);

  if (existingIndex === -1) {
    const nextVotes = state.votes.concat([{ voter, choice }]);
    return { result: 'recorded', state: { ...state, votes: nextVotes } };
  }

  if (state.votes[existingIndex].choice === choice) {
    return { result: 'unchanged', state };
  }

  const nextVotes = state.votes.slice();
  nextVotes[existingIndex] = { voter, choice };
  return { result: 'changed', state: { ...state, votes: nextVotes } };
}

function tally(state, now) {
  let tea = 0;
  let coffee = 0;
  for (const v of state.votes) {
    if (v.choice === 'tea') tea += 1;
    if (v.choice === 'coffee') coffee += 1;
  }
  return {
    result: { tea, coffee, closed: now >= state.closesAt },
    state,
  };
}

import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { execute } from '../src/index.mjs';

describe('tea-or-coffee poll', () => {
  it('records a new vote while open', () => {
    const state = { closesAt: 200, votes: [] };
    const { result, state: next } = execute({ operation: 'vote', input: { voter: 'Ari', choice: 'tea' }, state, now: 100 });
    assert.equal(result, 'recorded');
    assert.deepEqual(next, { closesAt: 200, votes: [{ voter: 'Ari', choice: 'tea' }] });
  });

  it('changes an existing vote while open', () => {
    const state = { closesAt: 200, votes: [{ voter: 'Ari', choice: 'tea' }] };
    const { result, state: next } = execute({ operation: 'vote', input: { voter: 'Ari', choice: 'coffee' }, state, now: 100 });
    assert.equal(result, 'changed');
    assert.deepEqual(next, { closesAt: 200, votes: [{ voter: 'Ari', choice: 'coffee' }] });
  });

  it('returns unchanged when voting the same choice', () => {
    const state = { closesAt: 200, votes: [{ voter: 'Ari', choice: 'coffee' }] };
    const { result, state: next } = execute({ operation: 'vote', input: { voter: 'Ari', choice: 'coffee' }, state, now: 100 });
    assert.equal(result, 'unchanged');
    assert.deepEqual(next, state);
  });

  it('rejects late votes without changing state', () => {
    const state = { closesAt: 200, votes: [{ voter: 'Ari', choice: 'tea' }] };
    const { result, state: next } = execute({ operation: 'vote', input: { voter: 'Bo', choice: 'coffee' }, state, now: 200 });
    assert.equal(result, 'closed');
    assert.deepEqual(next, state);
  });

  it('counts votes and reports deadline state', () => {
    const state = { closesAt: 200, votes: [{ voter: 'Ari', choice: 'coffee' }, { voter: 'Bo', choice: 'tea' }, { voter: 'Chi', choice: 'coffee' }] };
    const { result, state: next } = execute({ operation: 'tally', input: null, state, now: 150 });
    assert.deepEqual(result, { tea: 1, coffee: 2, closed: false });
    assert.deepEqual(next, state);
  });

  it('reports closed after deadline', () => {
    const state = { closesAt: 200, votes: [{ voter: 'Ari', choice: 'tea' }] };
    const { result } = execute({ operation: 'tally', input: null, state, now: 201 });
    assert.deepEqual(result, { tea: 1, coffee: 0, closed: true });
  });

  it('trims voter and rejects blank input', () => {
    const state = { closesAt: 200, votes: [] };
    const { result, state: next } = execute({ operation: 'vote', input: { voter: '   ', choice: 'tea' }, state, now: 100 });
    assert.equal(result, 'invalid');
    assert.deepEqual(next, state);
  });

  it('matches voters case-sensitively', () => {
    const state = { closesAt: 200, votes: [{ voter: 'Ari', choice: 'tea' }] };
    const { result, state: next } = execute({ operation: 'vote', input: { voter: 'ari', choice: 'coffee' }, state, now: 100 });
    assert.equal(result, 'recorded');
    assert.deepEqual(next, { closesAt: 200, votes: [{ voter: 'Ari', choice: 'tea' }, { voter: 'ari', choice: 'coffee' }] });
  });
});

// State, input validation and durable commits are managed by Restyle.
// No process-local data, wall-clock reads, timers or external services.
export function execute({ operation, input, state, now, connectionResults = [] }) {
  const closed = now >= state.closesAt;

  if (operation === 'tally') {
    let tea = 0;
    let coffee = 0;
    for (const vote of state.votes) {
      if (vote.choice === 'tea') tea += 1;
      if (vote.choice === 'coffee') coffee += 1;
    }
    return { result: { tea, coffee, closed }, state };
  }

  if (operation !== 'vote') {
    throw new Error('Unsupported operation');
  }
  // Deadline rejection takes precedence over voter validation.
  if (closed) return { result: 'closed', state };

  const voter = input.voter.trim();
  if (!voter) return { result: 'invalid', state };

  const index = state.votes.findIndex((vote) => vote.voter === voter);
  if (index !== -1) {
    if (state.votes[index].choice === input.choice) {
      return { result: 'unchanged', state };
    }
    const votes = state.votes.map((vote, position) =>
      position === index ? { voter, choice: input.choice } : { ...vote }
    );
    return { result: 'changed', state: { closesAt: state.closesAt, votes } };
  }

  // The agreed durable state holds at most 32 distinct voters.
  // Reject a new voter at capacity without changing any existing vote.
  if (state.votes.length >= 32) return { result: 'invalid', state };
  return {
    result: 'recorded',
    state: {
      closesAt: state.closesAt,
      votes: [...state.votes.map((vote) => ({ ...vote })), { voter, choice: input.choice }]
    }
  };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { execute } from '../src/poll.mjs';

const initial = () => ({ closesAt: 200, votes: [] });
const vote = (state, voter, choice, now = 100) =>
  execute({ operation: 'vote', input: { voter, choice }, state, now });
const tally = (state, now = 100) =>
  execute({ operation: 'tally', input: null, state, now });

function freezeState(state) {
  for (const item of state.votes) Object.freeze(item);
  Object.freeze(state.votes);
  return Object.freeze(state);
}

test('replays the immutable agreement example with exact results and states', () => {
  let state = initial();
  const recorded = vote(state, 'Ari', 'tea');
  assert.deepEqual(recorded, {
    result: 'recorded',
    state: { closesAt: 200, votes: [{ voter: 'Ari', choice: 'tea' }] }
  });
  state = recorded.state;
  const changed = vote(state, 'Ari', 'coffee');
  assert.deepEqual(changed, {
    result: 'changed',
    state: { closesAt: 200, votes: [{ voter: 'Ari', choice: 'coffee' }] }
  });
  assert.deepEqual(tally(changed.state), {
    result: { tea: 0, coffee: 1, closed: false }, state: changed.state
  });
});

test('duplicate choices are unchanged and never add a second vote', () => {
  const state = freezeState(vote(initial(), 'Ari', 'tea').state);
  assert.deepEqual(vote(state, 'Ari', 'tea'), { result: 'unchanged', state });
  assert.equal(state.votes.length, 1);
});

test('trims voters and treats a trimmed identifier as the same voter', () => {
  const first = vote(initial(), ' \tAri\n ', 'tea');
  assert.equal(first.result, 'recorded');
  assert.deepEqual(first.state.votes, [{ voter: 'Ari', choice: 'tea' }]);
  const second = vote(first.state, ' Ari ', 'coffee');
  assert.equal(second.result, 'changed');
  assert.deepEqual(second.state.votes, [{ voter: 'Ari', choice: 'coffee' }]);
});

test('rejects empty or whitespace-only identifiers without mutation', () => {
  const state = freezeState(initial());
  for (const voter of ['', ' ', '\t\n', '\u2003\u00a0']) {
    assert.deepEqual(vote(state, voter, 'tea'), { result: 'invalid', state });
  }
});

test('identifiers are case-sensitive and arbitrary text is not an object key', () => {
  let state = initial();
  for (const voter of ['Ari', 'ari', '__proto__', 'constructor', '茶']) {
    const response = vote(state, voter, 'tea');
    assert.equal(response.result, 'recorded');
    state = response.state;
  }
  assert.equal(state.votes.length, 5);
  assert.deepEqual(tally(state).result, { tea: 5, coffee: 0, closed: false });
});

test('allows votes immediately before the deadline and rejects equality and later', () => {
  const state = freezeState(initial());
  assert.equal(vote(state, 'Ari', 'tea', 199).result, 'recorded');
  for (const now of [200, 201, 9999999999999]) {
    assert.deepEqual(vote(state, 'Ari', 'tea', now), { result: 'closed', state });
    assert.deepEqual(tally(state, now), {
      result: { tea: 0, coffee: 0, closed: true }, state
    });
  }
});

test('late updates, repeat votes and blank votes all return closed first', () => {
  const state = freezeState(vote(initial(), 'Ari', 'tea', 199).state);
  for (const [voter, choice] of [['Ari', 'coffee'], ['Ari', 'tea'], ['', 'coffee'], ['New', 'tea']]) {
    assert.deepEqual(vote(state, voter, choice, 200), { result: 'closed', state });
  }
  assert.deepEqual(tally(state, 201).result, { tea: 1, coffee: 0, closed: true });
});

test('updates keep order and leave other voters unchanged', () => {
  const state = freezeState({ closesAt: 200, votes: [
    { voter: 'First', choice: 'tea' },
    { voter: 'Middle', choice: 'tea' },
    { voter: 'Last', choice: 'coffee' }
  ] });
  const updated = vote(state, 'Middle', 'coffee');
  assert.deepEqual(updated, { result: 'changed', state: { closesAt: 200, votes: [
    { voter: 'First', choice: 'tea' },
    { voter: 'Middle', choice: 'coffee' },
    { voter: 'Last', choice: 'coffee' }
  ] } });
  assert.equal(state.votes[1].choice, 'tea');
  assert.deepEqual(tally(updated.state).result, { tea: 1, coffee: 2, closed: false });
});

test('truthful totals survive serialization and reopening before and after closing', () => {
  let state = initial();
  state = vote(state, 'Ari', 'tea', 100).state;
  state = vote(state, 'Bea', 'coffee', 110).state;
  state = vote(state, 'Ari', 'coffee', 120).state;
  const reopened = freezeState(JSON.parse(JSON.stringify(state)));
  assert.deepEqual(tally(reopened, 150), {
    result: { tea: 0, coffee: 2, closed: false }, state: reopened
  });
  assert.deepEqual(tally(reopened, 200), {
    result: { tea: 0, coffee: 2, closed: true }, state: reopened
  });
  assert.deepEqual(vote(reopened, 'Bea', 'tea', 201), { result: 'closed', state: reopened });
});

test('uses supplied now and closesAt, never the machine wall clock', () => {
  const original = Date.now;
  Date.now = () => { throw new Error('Wall clock must not be consulted'); };
  try {
    const state = { closesAt: 9876543210000, votes: [] };
    assert.equal(vote(state, 'Ari', 'tea', 9876543209999).result, 'recorded');
    assert.equal(vote(state, 'Ari', 'tea', 9876543210000).result, 'closed');
    assert.equal(tally(state, 9876543209999).result.closed, false);
    assert.equal(tally(state, 9876543210000).result.closed, true);
    assert.equal(vote({ closesAt: 0, votes: [] }, 'Ari', 'tea', 0).result, 'closed');
  } finally {
    Date.now = original;
  }
});

test('does not mutate frozen state or input when recording', () => {
  const state = freezeState(initial());
  const input = Object.freeze({ voter: ' Ari ', choice: 'coffee' });
  const response = execute({ operation: 'vote', input, state, now: 1, connectionResults: [] });
  assert.deepEqual(response, {
    result: 'recorded', state: { closesAt: 200, votes: [{ voter: 'Ari', choice: 'coffee' }] }
  });
  assert.deepEqual(state, initial());
  assert.equal(input.voter, ' Ari ');
});

test('serialized competing requests preserve one vote per supplied voter', () => {
  let state = initial();
  for (const choice of ['tea', 'coffee', 'coffee', 'tea']) {
    state = vote(state, 'Ari', choice, 199).state;
    assert.equal(state.votes.length, 1);
  }
  state = vote(state, 'Bea', 'coffee', 199).state;
  assert.deepEqual(tally(state, 200).result, { tea: 1, coffee: 1, closed: true });
  assert.deepEqual(vote(state, 'Ari', 'coffee', 200), { result: 'closed', state });
});

test('capacity remains schema-valid while existing voters can still change', () => {
  let state = initial();
  for (let i = 0; i < 32; i++) {
    const response = vote(state, `V${i}`, i % 2 ? 'coffee' : 'tea');
    assert.equal(response.result, 'recorded');
    state = response.state;
  }
  state = freezeState(state);
  assert.deepEqual(tally(state).result, { tea: 16, coffee: 16, closed: false });
  assert.deepEqual(vote(state, 'Overflow', 'tea'), { result: 'invalid', state });
  assert.deepEqual(vote(state, 'V0', 'tea'), { result: 'unchanged', state });
  const changed = vote(state, 'V0', 'coffee');
  assert.equal(changed.result, 'changed');
  assert.equal(changed.state.votes.length, 32);
  assert.deepEqual(tally(changed.state).result, { tea: 15, coffee: 17, closed: false });
});

test('independent invocations rely only on their supplied durable state', () => {
  vote(initial(), 'Hidden', 'tea');
  assert.deepEqual(tally(initial()).result, { tea: 0, coffee: 0, closed: false });
  const state = freezeState({ closesAt: 200, votes: [{ voter: 'Saved', choice: 'coffee' }] });
  assert.deepEqual(tally(state).result, { tea: 0, coffee: 1, closed: false });
});

test('unknown operations fail rather than changing state', () => {
  const state = freezeState(initial());
  assert.throws(() => execute({ operation: 'reset', input: null, state, now: 100 }), /Unsupported operation/);
  assert.deepEqual(state, initial());
});
